const norm = (v) => String(v ?? '').trim().toUpperCase();

const rows = $input.all().map(i => i.json).filter(r => Object.keys(r).length > 0);

const publishable = rows.filter(r =>
  norm(r.ESTADO) === 'PUBLICADO' &&
  norm(r.PUBLICAR) === 'SI' &&
  norm(r.PRIVACIDAD) === 'PUBLICO'
);

const required = ['ID_NOTICIA', 'FECHA', 'SLUG', 'TITULO', 'RESUMEN'];
const invalid = publishable.filter(r => required.some(k => !String(r[k] ?? '').trim()));
if (invalid.length) {
  throw new Error(`Hay ${invalid.length} fila(s) PUBLICADAS con campos obligatorios vacíos. No se publica nada.`);
}

const ids = new Set();
const slugs = new Set();
for (const r of publishable) {
  const id = String(r.ID_NOTICIA).trim();
  const slug = String(r.SLUG).trim();
  if (ids.has(id)) throw new Error(`ID_NOTICIA duplicado: ${id}`);
  if (slugs.has(slug)) throw new Error(`SLUG duplicado: ${slug}`);
  ids.add(id);
  slugs.add(slug);
}

function dateKey(v) {
  const s = String(v ?? '').trim();
  const iso = Date.parse(s);
  if (!Number.isNaN(iso)) return iso;
  const m = s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);
  if (m) return new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1])).getTime();
  return 0;
}

const publicItems = publishable.map(r => ({
  id: String(r.ID_NOTICIA ?? '').trim(),
  fecha: String(r.FECHA ?? '').trim(),
  slug: String(r.SLUG ?? '').trim(),
  titulo: String(r.TITULO ?? '').trim(),
  resumen: String(r.RESUMEN ?? '').trim(),
  cuerpo: String(r.CUERPO ?? '').trim(),
  imagen: String(r.IMAGEN_REF ?? '').trim()
})).sort((a, b) => dateKey(b.fecha) - dateKey(a.fecha));

return [{
  json: {
    payload: {
      schema_version: '1.0',
      generated_at: new Date().toISOString(),
      source: 'SIM_WEB_NOTICIAS',
      items: publicItems
    },
    audit: {
      total_rows: rows.length,
      publishable_rows: publicItems.length,
      gate: 'ESTADO=PUBLICADO && PUBLICAR=SI && PRIVACIDAD=PUBLICO',
      target_branch: 'portal-shell-v6',
      target_path: 'preview-v6/data/noticias.json'
    }
  }
}];

const current = $input.first().json;
const built = $('Construir JSON público').first().json;
const text = JSON.stringify(built.payload, null, 2) + '\n';
const content = Buffer.from(text, 'utf8').toString('base64');

return [{
  json: {
    body: {
      message: `LAB: publicar ${built.payload.items.length} noticia(s) desde SIM_WEB_NOTICIAS`,
      content,
      sha: current.sha,
      branch: 'portal-shell-v6'
    },
    audit: built.audit,
    payload: built.payload
  }
}];

const github = $input.first().json;
const built = $('Construir JSON público').first().json;
return [{
  json: {
    ok: true,
    published_items: built.payload.items.length,
    generated_at: built.payload.generated_at,
    branch: 'portal-shell-v6',
    path: 'preview-v6/data/noticias.json',
    github_commit: github.commit?.sha ?? null,
    github_content_sha: github.content?.sha ?? null
  }
}];
